@Override
public int read() throws IOException {
    if (fileStream != null) {
        int b = fileStream.read();
        if (b != -1) {
            filePosition++;
        }
        return b;
    }
    if (cachingStream != null) {
        return cachingStream.read();
    }
    int b = passthroughStream.read();
    if (b != -1) {
        passthroughPosition++;
    }
    return b;
}
